class WorkspacePhase(enum.Enum):
    """
    Core's workspace phase. It is exhaustive in core, so UniFFI exports it
    as a remote type with no mirror.
"""
    
    EMPTY = 0
    
    CREATING = 1
    
    JOINING = 2
    
    SYNCHRONIZING = 3
    
    ACTIVE = 4
    
    RECOVERING = 5
    
    LEAVING = 6
    
    RESETTING = 7
    
