@dataclass
class WorkspaceState:
    """
    The workspace state of a client.
"""
    def __init__(self, *, endpoint_id:EndpointId, workspace:typing.Optional[WorkspaceId], workspace_ready:bool, durable:bool, phase:WorkspacePhase, reason:typing.Optional[str]):
        self.endpoint_id = endpoint_id
        self.workspace = workspace
        self.workspace_ready = workspace_ready
        self.durable = durable
        self.phase = phase
        self.reason = reason
        
        

    
    def __str__(self):
        return "WorkspaceState(endpoint_id={}, workspace={}, workspace_ready={}, durable={}, phase={}, reason={})".format(self.endpoint_id, self.workspace, self.workspace_ready, self.durable, self.phase, self.reason)
    def __eq__(self, other):
        if self.endpoint_id != other.endpoint_id:
            return False
        if self.workspace != other.workspace:
            return False
        if self.workspace_ready != other.workspace_ready:
            return False
        if self.durable != other.durable:
            return False
        if self.phase != other.phase:
            return False
        if self.reason != other.reason:
            return False
        return True

