# ApiError
# We want to define each variant as a nested class that's also a subclass,
# which is tricky in Python.  To accomplish this we're going to create each
# class separately, then manually add the child classes to the base class's
# __dict__.  All of this happens in dummy class to avoid polluting the module
# namespace.
class ApiError(Exception):
    """
    The error of every SDK call. Programs read `api_error_code(error)`; the
    text is for people and never holds secrets.
"""
    pass

_UniffiTempApiError = ApiError

class ApiError:  # type: ignore
    """
    The error of every SDK call. Programs read `api_error_code(error)`; the
    text is for people and never holds secrets.
"""
    
    class Closed(_UniffiTempApiError):
        
        def __init__(self):
            pass

        def __repr__(self):
            return "ApiError.Closed({})".format(str(self))
    _UniffiTempApiError.Closed = Closed # type: ignore
    class Cancelled(_UniffiTempApiError):
        
        def __init__(self):
            pass

        def __repr__(self):
            return "ApiError.Cancelled({})".format(str(self))
    _UniffiTempApiError.Cancelled = Cancelled # type: ignore
    class DeadlineExceeded(_UniffiTempApiError):
        
        def __init__(self):
            pass

        def __repr__(self):
            return "ApiError.DeadlineExceeded({})".format(str(self))
    _UniffiTempApiError.DeadlineExceeded = DeadlineExceeded # type: ignore
    class InvalidInput(_UniffiTempApiError):
        
        def __init__(self, field, reason):
            super().__init__(", ".join([
                "field={!r}".format(field),
                "reason={!r}".format(reason),
            ]))
            self.field = field
            self.reason = reason

        def __repr__(self):
            return "ApiError.InvalidInput({})".format(str(self))
    _UniffiTempApiError.InvalidInput = InvalidInput # type: ignore
    class InvalidId(_UniffiTempApiError):
        
        def __init__(self, kind, reason):
            super().__init__(", ".join([
                "kind={!r}".format(kind),
                "reason={!r}".format(reason),
            ]))
            self.kind = kind
            self.reason = reason

        def __repr__(self):
            return "ApiError.InvalidId({})".format(str(self))
    _UniffiTempApiError.InvalidId = InvalidId # type: ignore
    class CapacityExceeded(_UniffiTempApiError):
        
        def __init__(self, resource, limit, detail):
            super().__init__(", ".join([
                "resource={!r}".format(resource),
                "limit={!r}".format(limit),
                "detail={!r}".format(detail),
            ]))
            self.resource = resource
            self.limit = limit
            self.detail = detail

        def __repr__(self):
            return "ApiError.CapacityExceeded({})".format(str(self))
    _UniffiTempApiError.CapacityExceeded = CapacityExceeded # type: ignore
    class LimitReached(_UniffiTempApiError):
        
        def __init__(self, resource, limit, detail):
            super().__init__(", ".join([
                "resource={!r}".format(resource),
                "limit={!r}".format(limit),
                "detail={!r}".format(detail),
            ]))
            self.resource = resource
            self.limit = limit
            self.detail = detail

        def __repr__(self):
            return "ApiError.LimitReached({})".format(str(self))
    _UniffiTempApiError.LimitReached = LimitReached # type: ignore
    class Storage(_UniffiTempApiError):
        
        def __init__(self, code, detail):
            super().__init__(", ".join([
                "code={!r}".format(code),
                "detail={!r}".format(detail),
            ]))
            self.code = code
            self.detail = detail

        def __repr__(self):
            return "ApiError.Storage({})".format(str(self))
    _UniffiTempApiError.Storage = Storage # type: ignore
    class Transport(_UniffiTempApiError):
        
        def __init__(self, code, peer, detail):
            super().__init__(", ".join([
                "code={!r}".format(code),
                "peer={!r}".format(peer),
                "detail={!r}".format(detail),
            ]))
            self.code = code
            self.peer = peer
            self.detail = detail

        def __repr__(self):
            return "ApiError.Transport({})".format(str(self))
    _UniffiTempApiError.Transport = Transport # type: ignore
    class Authorization(_UniffiTempApiError):
        
        def __init__(self, code, detail):
            super().__init__(", ".join([
                "code={!r}".format(code),
                "detail={!r}".format(detail),
            ]))
            self.code = code
            self.detail = detail

        def __repr__(self):
            return "ApiError.Authorization({})".format(str(self))
    _UniffiTempApiError.Authorization = Authorization # type: ignore
    class State(_UniffiTempApiError):
        
        def __init__(self, code, detail):
            super().__init__(", ".join([
                "code={!r}".format(code),
                "detail={!r}".format(detail),
            ]))
            self.code = code
            self.detail = detail

        def __repr__(self):
            return "ApiError.State({})".format(str(self))
    _UniffiTempApiError.State = State # type: ignore
    class Internal(_UniffiTempApiError):
        
        def __init__(self, detail):
            super().__init__(", ".join([
                "detail={!r}".format(detail),
            ]))
            self.detail = detail

        def __repr__(self):
            return "ApiError.Internal({})".format(str(self))
    _UniffiTempApiError.Internal = Internal # type: ignore

ApiError = _UniffiTempApiError # type: ignore
del _UniffiTempApiError


